{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may not terminate a tenancy without just cause; at-fault causes include nonpayment, lease violations and nuisance, while no-fault causes such as owner move-in or demolition require relocation assistance. Landlords may not evict where rent owed is below Fair Market Rent.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles not regulated by the RSO. A tenancy is covered once the tenant has lived in the unit at least six months or the original lease expired, whichever comes first.","applicability":{"conditions":[{"type":"other","role":"exempt","text":"residential properties regulated by the City's Rent Stabilization Ordinance (RSO)"},{"type":"owner","role":"exempt","who":"owned by HACLA or the government","unit_limit":null}],"per_tenancy":"Tenant has lived in the same unit at least six months or their original lease expired, whichever comes first.","coverage_quotes":["The JCO covers most residential properties in the City of Los Angeles that are not regulated by the City’s Rent Stabilization Ordinance (RSO).","In order to apply to a tenancy, it requires that the tenant either has lived in the same unit for at least six months or that their original lease expired, whichever comes first.","some properties owned by HACLA or the government"]},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless and short-term substance-abuse treatment centers, and HACLA- or government-owned properties.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act of 2019 (AB 1482) rent cap","requirement":"Annual rent increases for covered units are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower; the maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025 (previously 8.8%).","key_value":"5% + CPI, max 10%; 8.9% for Aug 1, 2024 – Jul 31, 2025","coverage_conditions":"Buildings older than 15 years, applied on a rolling basis. Excludes newer construction, deed-restricted affordable units, certain dormitories, owner-occupied two-unit properties, qualifying single-family homes and condominiums, and RSO units.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"owner","role":"exempt","who":"owner-occupied two-unit property","unit_limit":2},{"type":"other","role":"exempt","text":"units restricted by a deed or recorded document limiting affordability to low- or moderate-income households"},{"type":"other","role":"exempt","text":"single-family homes and condominiums not owned by a trust, corporation or corporate LLC, where the landlord gave written notice"}],"per_tenancy":null,"coverage_quotes":["The JCO does not regulate rent increases, however, state law AB 1482, the California Tenant Protection Act of 2019, may regulate the rent amount in buildings that are older than 15 years old.","Units that were constructed within the last 15 years (this applies on a rolling basis – i.e.. a unit constructed on January 1, 2006 is not covered as of January, 1 2020, but is covered on and after January 1, 2021).","Units restricted by a deed, regulatory restrictions, or other recorded document limiting the affordability to low or moderate-income households."]},"exemptions":"Units built within the last 15 years; deed-restricted affordable units; certain dormitories; two-unit properties with an owner-occupied second unit; qualifying single-family homes and condominiums; units already subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","valid_through":null,"citation":"AB 1482 (Cal. Civ. Code § 1947.12)","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":null,"relations":[{"type":"yields_to_local","quote":"Units that are already subject to the City’s RSO."}],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
